import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.DrDMl0tG.js";const s="/assets/templated_tracked_robot.C8A8XQT4.png",b=JSON.parse('{"title":"Server Example: Templated Tracked Robot","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/templated_tracked_robot.md","filePath":"sections/examples/server/templated_tracked_robot.md"}'),l={name:"sections/examples/server/templated_tracked_robot.md"};function i(d,e,c,p,n,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="server-example-templated-tracked-robot" tabindex="-1">Server Example: Templated Tracked Robot <a class="header-anchor" href="#server-example-templated-tracked-robot" aria-label="Permalink to &quot;Server Example: Templated Tracked Robot&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Loads a templated tracked robot URDF with parameter overrides and drives it over a row of steps. Its four belts are URDF <code>&lt;track&gt;</code> elements (see <a href="./../../articulated_system/Tracks.html">Tracks</a>), so the controller only sets PD targets on the two sprockets and the two flippers. It also shows how to customize URDF parameters programmatically.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+s+'" alt="templated_tracked_robot example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>templated_tracked_robot</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/templated_tracked_robot</span></span></code></pre></div><p>On Windows, run <code>templated_tracked_robot.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Instantiates a templated tracked robot URDF with parameter overrides (<code>rsc/templatedTrackedRobot/trackedTemplate.urdf</code>).</li><li>The main tracks wrap a sprocket and an idler; each flipper&#39;s track is driven from the sprocket&#39;s shaft, so it moves at the main belt&#39;s speed relative to the ground.</li><li>Drives the sprockets at 5 rad/s (velocity control, 0.89 m/s belt speed) and holds the flippers raised at 0.6 rad (position control); the robot climbs the steps with its flippers.</li><li>Adds a sequence of box obstacles in front of the robot.</li></ul>',13)])])}const _=t(l,[["render",i]]);export{b as __pageData,_ as default};
